import json,urllib.request,time
from pathlib import Path
r={'checks':[],'state':'running'}
p=Path('artifacts/docker-api-smoke.json')
def save(): p.write_text(json.dumps(r,ensure_ascii=False,indent=2))
def call(url,body=None):
 data=None if body is None else json.dumps(body).encode()
 with urllib.request.urlopen(urllib.request.Request(url,data=data,headers={'Content-Type':'application/json'}),timeout=300) as f: return json.load(f)
try:
 for port in [8000,8100]:
  result=call(f'http://127.0.0.1:{port}/health'); assert result['status']=='ok'; r['checks'].append({'health_port':port,'result':result})
 qs={d['id']:d for d in map(json.loads,Path('data/questions_dev.jsonl').read_text().splitlines())}
 for qid,confirm in [('dev-17',False),('dev-21',False),('dev-21',True)]:
  start=time.monotonic(); result=call('http://127.0.0.1:8000/ask',{'question':qs[qid]['question'],'mode':'agent','confirm':confirm})
  r['checks'].append({'id':qid,'confirm':confirm,'seconds':round(time.monotonic()-start,2),'response':result}); save()
  if qid=='dev-17':
   assert all(str(v) in result['answer'] for v in ['P-1042B','2630'])
  elif not confirm:
   assert result['needs_confirmation']; assert result['pending_action']==qs[qid]['expected_pending']
  else:
   assert not result['needs_confirmation']; assert 'SO-' in result['answer']
 r['state']='completed'
except Exception as e: r['state']='failed'; r['error']=repr(e)
save(); print(json.dumps(r,ensure_ascii=False,indent=2),flush=True)
